import {createEngine,replay,SCENARIO,RULE_VERSION} from './ledger-engine.mjs';
const $=id=>document.getElementById(id);
const money=cents=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let engine=createEngine(),s=engine.snapshot(),timer=null,view='journals';
function stop(){clearInterval(timer);timer=null;$('play').textContent='▶ Play month';}
function selectDay(day){stop();engine=createEngine({aprBps:Number($('apr').value)});for(let i=0;i<day;i++)engine.step();s=engine.snapshot();render();}
function step(){s=engine.step();if(s.day===31)stop();render();}
function chart(){const w=650,h=260,left=64,right=20,top=20,bottom=37;const ymax=Math.max(140000,...s.days.map(x=>x.balance));const x=d=>left+d/31*(w-left-right),y=n=>h-bottom-n/ymax*(h-top-bottom);const points=[{day:0,balance:0},...s.days];const path=points.map((p,i)=>`${i?'L':'M'} ${x(p.day)} ${y(p.balance)}`).join(' ');$('chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Daily posted receivable through January ${s.day||'start'}; current balance ${money(s.balance)}"><title>Computed daily receivable</title>${[0,50000,100000].map(n=>`<line x1="${left}" y1="${y(n)}" x2="${w-right}" y2="${y(n)}" stroke="#d9e3d8"/><text x="${left-9}" y="${y(n)+5}" text-anchor="end">${money(n)}</text>`).join('')}<path d="${path}" fill="none" stroke="#285c3b" stroke-width="3"/>${s.days.filter(d=>SCENARIO.some(e=>e.day===d.day)||d.day===31).map(p=>`<circle cx="${x(p.day)}" cy="${y(p.balance)}" r="4" fill="#285c3b"><title>Jan ${p.day}: ${money(p.balance)}</title></circle>`).join('')}<circle cx="${x(s.day)}" cy="${y(s.balance)}" r="6" fill="#c0d990" stroke="#285c3b" stroke-width="2"/>${[1,7,15,24,31].map(d=>`<text x="${x(d)}" y="${h-10}" text-anchor="middle">Jan ${d}</text>`).join('')}</svg>`;}
function render(){ $('date').textContent=s.day?`January ${s.day}, 2026`:'Before January 1';$('day').value=s.day;$('progress').textContent=`${s.day} of 31 days`;$('step').disabled=s.day===31;$('finish').disabled=s.day===31;const today=s.attempts.filter(a=>a.day===s.day);$('narrative').textContent=s.day===31?'Cycle closed. Interest assessed, balances reconciled, and a reproducible demo snapshot created.':today.length?today.map(a=>`${a.label}: ${a.status}. ${a.reason}.`).join(' '):s.day?'No incoming transaction today. The principal balance contributes to the daily interest calculation.':'Press Play to follow the account through its first cycle.';
 for(const key of ['balance','principal'])$(key).textContent=money(s[key]);$('assessed').textContent=money(s.fees+s.interest);$('assessed-note').textContent=`Interest ${money(s.interest)} · fees ${money(s.fees)}`;$('accrued').textContent=money(s.unbilledInterestCents);chart();
 $('checks').innerHTML=[['Journal debits − credits',money(s.checks.journalDifference),s.checks.journalDifference===0],['Ledger − account balance',money(s.checks.receivableDifference),s.checks.receivableDifference===0],['Unique journal event IDs',s.checks.uniqueJournalEvents?'Verified':'Failed',s.checks.uniqueJournalEvents]].map(([label,value,ok])=>`<span class="${ok?'':'bad'}">${ok?'✓':'!'} ${label}: ${value}</span>`).join('');
 const inputs=[...SCENARIO,{day:31,label:'Cycle close · assess interest',event:{id:'statement-interest',cents:s.interest,type:'interest'}}];$('events').innerHTML=inputs.map((i,index)=>{const a=s.attempts.find(a=>a.day===i.day&&a.eventId===i.event.id);return `<div class="event ${a?'':'future'}"><span class="when">JAN<br><b>${i.day}</b></span><div><b>${esc(i.label)}</b><small>${a?esc(a.reason):'Waiting for this business date'}</small><span class="state ${a?.status||''}">${a?.status||'scheduled'}</span></div><span class="money">${i.event.currency==='EUR'?'EUR 50.00':i.day===31&&!s.interest?'At close':money(i.event.cents)}</span></div>`;}).join('');evidence(); }
function evidence(){let html='';if(view==='journals'){html=s.journals.length?s.journals.map(j=>`<details><summary>Jan ${j.day} · ${j.id} · ${esc(j.label)} · ${money(j.cents)}</summary><p>Source: <code>${esc(j.eventId)}</code> · ${j.entity} · ${j.currency} · ${j.ruleVersion}${j.reverses?` · reverses ${esc(j.reverses)}`:''}</p><div class="table-wrap"><table><thead><tr><th>Account</th><th>Debit</th><th>Credit</th></tr></thead><tbody>${j.lines.map(l=>`<tr><td>${l.account}</td><td class="amount">${money(l.debit)}</td><td class="amount">${money(l.credit)}</td></tr>`).join('')}</tbody></table></div></details>`).join(''):'<p class="empty">No postings yet. The first purchase arrives on January 3.</p>';}
 if(view==='days')html=s.days.length?`<div class="table-wrap"><table><thead><tr><th>Business date</th><th>Principal</th><th>Fees</th><th>Interest assessed</th><th>Total receivable</th><th>Unbilled estimate</th></tr></thead><tbody>${s.days.map(d=>`<tr><td>Jan ${d.day}</td>${['principal','fees','interest','balance','unbilledInterestCents'].map(k=>`<td class="amount">${money(d[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<p class="empty">Advance the calendar to calculate daily balances.</p>';
 if(view==='statement')html=s.statement?`<div class="statement"><span class="state done">Reproducible demo snapshot</span><h3>January 31 · ${s.account.id}</h3><dl><dt>Principal</dt><dd>${money(s.principal)}</dd><dt>Service fee</dt><dd>${money(s.fees)}</dd><dt>Assessed interest</dt><dd>${money(s.interest)}</dd><dt>Closing receivable</dt><dd>${money(s.balance)}</dd></dl><p>Not a compliant customer statement. Minimum due, due date, grace period, required disclosures and delivery evidence are not implemented.</p></div>`:'<p class="empty">Run to January 31 to create the cycle snapshot.</p>';
 if(view==='rules')html=`<div class="rule-text"><h3>Transparent, deliberately bounded rules</h3><ul><li>USD minor units (integer cents); one account and one legal entity. No FX netting.</li><li>Purchases debit principal receivable and credit processor clearing. Payments debit payment clearing; refunds and reversals debit processor clearing. Cash settlement is not implied.</li><li>A single purchase balance earns illustrative ${s.account.aprBps/100}% annual interest. Each day contributes closing principal × APR basis points / 3,650,000. Accumulation uses BigInt rational arithmetic; half-up rounding occurs once at cycle close.</li><li>Payment reduces principal only. No minimum/excess allocation, grace period, compounding, backdated recalculation, disputes, or real fee eligibility. The $25 service fee is a synthetic event, not a late-fee policy.</li><li>Identical scoped event retries have no additional financial effect; conflicting content and EUR inputs are rejected. A reversal creates a linked compensating journal and retains the original.</li><li>All state lives in browser memory. Reload, Reset, day scrubbing and APR changes rebuild it. This is deterministic replay, not durable storage or a tamper-proof audit log.</li></ul><p>Rule version <code>${RULE_VERSION}</code>. Download the evidence to inspect inputs, outcomes, daily balances, calculation numerator and journals.</p></div>`;
 $('evidence').innerHTML=html;}
$('play').onclick=()=>{if(timer){stop();return;}if(s.day===31)selectDay(0);$('play').textContent='Ⅱ Pause';timer=setInterval(step,650);};$('step').onclick=()=>{stop();step();};$('finish').onclick=()=>selectDay(31);$('reset').onclick=()=>selectDay(0);$('day').oninput=e=>selectDay(Number(e.target.value));$('apr').onchange=()=>selectDay(0);
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));evidence();});
$('export').onclick=()=>{stop();const verified=JSON.stringify(replay(s.day,{aprBps:s.account.aprBps}))===JSON.stringify(s);const payload={purpose:'Synthetic executable demo evidence; not production accounting',inputs:SCENARIO,replayVerified:verified,...s};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`ar-demo-day-${s.day}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};render();
